import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import vm from 'node:vm';

// The complete shared module runs against read-only native fixtures. Input
// acknowledgements are explicit test actions, never generated by the renderer.
const source = readFileSync(new URL('../js/hd-battle.js', import.meta.url), 'utf8');
const K = {RIGHT:37,DOWN:35,ENTER:39,EXIT:40};
function fixture({mobile=true,storageThrows=false}={}) {
    let now=1000,next=1,available=true,libraryGeneration=1,revision='a',presentation='hd',providerHook=null,reads=0;
    const sent=[],writes=[],renders=[],listeners={},docListeners={},viewListeners={},timers=new Map(),intervals=[];
    const stored=new Map([['baye/battleMode','classic'],['baye/overworldMode','classic']]);
    const fight={active:1,over:0,wait:1,phase:1,inputKind:1,inputSeq:7,actorIndex:255,aimType:255};
    const menu={active:0,context:3,kind:0,seq:4,index:0,count:0,names:[]};
    const report={active:0};
    const positions=Array.from({length:20},()=>({x:0,y:0,active:0,state:8,hp:0,mp:0}));
    positions[0]={x:1,y:1,active:0,state:0,hp:100,mp:80};
    positions[1]={x:3,y:1,active:0,state:0,hp:90,mp:70};
    positions[10]={x:5,y:2,active:0,state:0,hp:80,mp:60};
    const ids=Array(20).fill(0);ids[0]=1;ids[1]=2;ids[10]=3;
    const raw={g_FoucsX:1,g_FoucsY:1,g_MapWid:8,g_MapHgt:8,g_FgtParam:{GenArray:ids},
        g_GenPos:positions,g_Persons:[{Arms:100},{Arms:100},{Arms:100}],g_FightMapData:Array(64).fill(1),
        g_FightPath:Array(225).fill(0),g_PathSX:0,g_PathSY:0,g_PUseSX:0,g_PUseSY:0,
        g_FgtAtkRng:[8,0,0,...Array(64).fill(1)],g_hdFightMenuControl:0,g_hdFightAllowRetreat:0};
    const data=new Proxy(raw,{set(target,key){writes.push(key);throw Error('native write '+key);}});
    const rootNode={classList:{toggle(){}},setAttribute(){},querySelectorAll(){return [];},
        addEventListener(type,fn){(listeners['root:'+type]||=[]).push(fn);}};
    const document={hidden:false,documentElement:{setAttribute(){}},body:{classList:{toggle(){}}},
        getElementById(id){return id==='hd-battle'?rootNode:null;},
        addEventListener(type,fn){(docListeners[type]||=[]).push(fn);}};
    class Clock extends Date {static now(){return now;}}
    const env={document,Date:Clock,console:{log(){},warn(){},error(e){throw e;}},devicePixelRatio:1,
        localStorage:{getItem(key){if(storageThrows)throw Error('blocked');return stored.get(key)||null;},
            setItem(key,value){if(storageThrows)throw Error('blocked');stored.set(key,value);}},
        setTimeout(fn,delay){const id=next++;timers.set(id,{fn,due:now+delay});return id;},clearTimeout(id){timers.delete(id);},
        setInterval(fn){intervals.push(fn);return intervals.length;},clearInterval(){},requestAnimationFrame(){return next++;},cancelAnimationFrame(){},
        addEventListener(type,fn){(listeners[type]||=[]).push(fn);},
        visualViewport:{addEventListener(type,fn){(viewListeners[type]||=[]).push(fn);}},
        BayeHdLibIdentity:{subscribe(fn){env.libraryChanged=fn;}},BayeHdOverworld:{getMode(){return 'hd-map';}},
        baye:{data,hooks:{},ensureData(){return env.baye.data;},getPersonName(id){return ['甲','乙','敌'][id];},getArmType(){return 1;},
            hd:{ready(){return true;},fight(){return {...fight};},menuItems(){return {...menu,names:menu.names.slice()};},report(){return {...report};}}},
        sendKey(key){sent.push(key);}};
    env.window=env;
    vm.runInNewContext(source,env,{filename:'js/hd-battle.js'});
    const api=env.BayeHdBattle;
    function readTicket(){
        reads+=1;if(providerHook)providerHook(reads);
        const stableKey=JSON.stringify([revision,libraryGeneration,fight.inputKind,fight.inputSeq,fight.actorIndex,
            menu.active,menu.context,menu.kind,menu.seq,menu.names,raw.g_FgtParam.GenArray,raw.g_GenPos,raw.g_FightPath,raw.g_FgtAtkRng]);
        return {data:env.baye.data,key:JSON.stringify([stableKey,raw.g_FoucsX,raw.g_FoucsY,menu.index]),stableKey,
            libraryGeneration,kind:fight.inputKind,seq:fight.inputSeq,actor:fight.actorIndex,presentation};
    }
    const options={isAvailable:()=>available,readTicket,render(snapshot){renders.push(snapshot);}};
    if(mobile)api.configureMobileHost(options);
    api.start();if(mobile)api.onEngineFight();
    function tick(ms=16){now+=ms;for(const [id,item] of [...timers])if(item.due<=now&&timers.delete(id))item.fn();}
    return {env,api,raw,data,fight,menu,report,sent,writes,renders,stored,timers,listeners,options,
        tick,poll(){intervals.forEach(fn=>fn());},focus(x,y){raw.g_FoucsX=x;raw.g_FoucsY=y;},
        emit(name){(listeners[name]||[]).forEach(fn=>fn());},
        hidden(value){document.hidden=value;(docListeners.visibilitychange||[]).forEach(fn=>fn());},
        viewport(){(viewListeners.resize||[]).forEach(fn=>fn());},
        setAvailable(value){available=value;},setPresentation(value){presentation=value;},
        changeOwner(){revision+='x';},changeLibrary(){libraryGeneration+=1;},
        providerHook(fn){providerHook=fn;reads=0;},
        openMenu(kind=3){Object.assign(fight,{inputKind:kind,inputSeq:fight.inputSeq+1,actorIndex:0,wait:0});
            Object.assign(menu,{active:1,kind,seq:menu.seq+1,index:0,count:3,names:['攻击','计谋','待机']});api.onEngineFight();}};
}

test('mobile uses independent mode and storage failure retains the in-memory preference',()=>{
    const f=fixture();assert.equal(f.api.getMode(),'auto');assert.equal(f.api.shouldShowHd(),true);
    f.api.setMode('classic');assert.equal(f.stored.get('baye/mobileBattleMode'),'classic');
    assert.equal(f.stored.get('baye/battleMode'),'classic');assert.equal(f.api.getInputTicket(),null);
    f.api.setMode('hd');assert.ok(f.api.getInputTicket());assert.deepEqual(f.sent,[]);assert.deepEqual(f.writes,[]);
    const g=fixture({storageThrows:true});g.api.setMode('classic');assert.equal(g.api.getMode(),'classic');
    g.api.setMode('hd');assert.equal(g.api.getMode(),'hd');
});
test('mobile binds no shared naked click or keydown; PC still binds both',()=>{
    const f=fixture();assert.equal(f.listeners['root:click'],undefined);assert.equal(f.listeners.keydown,undefined);
    const pc=fixture({mobile:false});assert.equal(pc.listeners['root:click'].length,1);assert.equal(pc.listeners.keydown.length,1);
    assert.equal(pc.api.getInputTicket(),null);assert.equal(pc.api.getMode(),'classic');
});
test('mobile operation ticket is immutable with opaque non-enumerable data and complete focus key',()=>{
    const f=fixture(),a=f.api.getInputTicket();assert.equal(a.data,f.data);assert.ok(Object.isFrozen(a));
    assert.equal(Object.keys(a).includes('data'),false);f.focus(2,1);const b=f.api.getInputTicket();
    assert.notEqual(a.key,b.key);assert.equal(a.stableKey,b.stableKey);assert.deepEqual(f.writes,[]);
});
test('mobile render receives copied units and full copied terrain without native data',()=>{
    const f=fixture(),payload=f.renders.at(-1);assert.ok(payload);assert.equal(payload.terrainSnapshot.tiles.length,64);
    assert.equal('data' in payload,false);payload.unitList[0].x=7;payload.terrainSnapshot.tiles[0]=255;
    const after=f.api.debugSnapshot();assert.equal(after.unitList[0].x,1);
    f.poll();assert.equal(f.renders.at(-1).terrainSnapshot.tiles[0],1);assert.deepEqual(f.sent,[]);
});
test('mobile renderer reentry cannot recursively draw or send input',()=>{
    const f=fixture();let calls=0;f.options.render=()=>{calls+=1;f.api.recoverMenu();};
    f.poll();assert.equal(calls,1);assert.deepEqual(f.sent,[]);
});
test('mobile tile movement waits for each real focus ACK then sends one Enter',()=>{
    const f=fixture();assert.equal(f.api.clickTile(3,1).ok,true);assert.deepEqual(f.sent,[K.RIGHT]);
    f.tick(100);assert.deepEqual(f.sent,[K.RIGHT]);f.focus(2,1);f.tick();assert.deepEqual(f.sent,[K.RIGHT,K.RIGHT]);
    f.focus(3,1);f.tick();assert.deepEqual(f.sent,[K.RIGHT,K.RIGHT,K.ENTER]);
    f.api.clickTile(3,1);f.tick();assert.equal(f.sent.length,3);
});
test('mobile menu index ACK may change while full names and stable owner remain exact',()=>{
    const f=fixture();f.openMenu();assert.equal(f.api.pickMenu(1).ok,true);assert.deepEqual(f.sent,[K.DOWN]);
    f.tick();assert.equal(f.sent.length,1);f.menu.index=1;f.tick();assert.deepEqual(f.sent,[K.DOWN,K.ENTER]);
});
for(const changed of ['names','mask','unit','library','data','actor','seq']){
    test('mobile transaction retires when '+changed+' changes before the next key',()=>{
        const f=fixture();f.api.clickTile(3,1);const callbacks=[...f.timers.values()].map(x=>x.fn);f.focus(2,1);
        if(changed==='names')f.menu.names=['新菜单'];if(changed==='mask')f.raw.g_FightPath[0]=255;
        if(changed==='unit')f.raw.g_GenPos[0].hp-=1;if(changed==='library')f.changeLibrary();
        if(changed==='data')f.env.baye.data={...f.raw};if(changed==='actor')f.fight.actorIndex=0;if(changed==='seq')f.fight.inputSeq+=1;
        callbacks.forEach(fn=>fn());f.tick();assert.deepEqual(f.sent,[K.RIGHT]);assert.equal(f.api.debugSnapshot().transaction,null);
    });
}
test('mobile exact ticket rejects torn provider reads',()=>{
    const f=fixture();f.providerHook(()=>f.changeOwner());assert.equal(f.api.getInputTicket(),null);
    assert.equal(f.api.clickTile(1,1).ok,false);assert.deepEqual(f.sent,[]);
});
for(const field of ['data','key','stableKey','libraryGeneration','kind','seq','actor']){
    test('final physical-send fence rejects changed '+field+' after a transaction was authorized',()=>{
        const begin=source.indexOf('    function rawSendKey(code) {'),end=source.indexOf('    function finishRequest(',begin);
        const sameBegin=source.indexOf('    function sameMobileTicket('),sameEnd=source.indexOf('    function shouldShowHd(',sameBegin);
        assert.ok(begin>=0&&end>begin&&sameBegin>=0&&sameEnd>sameBegin);
        const data={},owner={data,key:'full',stableKey:'stable',libraryGeneration:1,kind:1,seq:7,actor:255};
        let fresh={...owner};const sent=[];
        const context={mobileHost:{},state:{transaction:{mobileStepOwner:owner}},getInputTicket(){return fresh;},
            global:{sendKey(key){sent.push(key);}}};
        vm.runInNewContext(source.slice(sameBegin,sameEnd)+source.slice(begin,end),context);
        assert.equal(context.rawSendKey(K.ENTER),true);assert.deepEqual(sent,[K.ENTER]);
        fresh={...owner,[field]:field==='data'?{}:field==='key'||field==='stableKey'?'changed':owner[field]+1};
        assert.equal(context.rawSendKey(K.ENTER),false);assert.deepEqual(sent,[K.ENTER]);
        fresh=null;assert.equal(context.rawSendKey(K.ENTER),false);assert.deepEqual(sent,[K.ENTER]);
    });
}
for(const kind of [0,9,10]){
    test('LCD presentation kind '+kind+' is observable but never authorizes shared HD input',()=>{
        const f=fixture();Object.assign(f.fight,{inputKind:kind,actorIndex:255});f.setPresentation('lcd');
        assert.equal(f.api.shouldShowHd(),true);assert.equal(f.api.getInputTicket(),null);
        assert.equal(f.api.getLcdPresentation(),'passthrough');assert.equal(f.api.openSystemMenu().ok,false);assert.deepEqual(f.sent,[]);
    });
}
test('report, malformed presentation and local LCD switch refuse HD keys',()=>{
    const f=fixture();f.report.active=1;assert.equal(f.api.getInputTicket(),null);assert.equal(f.api.getLcdPresentation(),'passthrough');
    f.report.active=0;f.setPresentation(undefined);assert.equal(f.api.shouldShowHd(),false);assert.equal(f.api.getInputTicket(),null);
    f.setPresentation('hd');f.api.setShowLcd(true);assert.equal(f.api.getInputTicket(),null);
    assert.equal(f.api.getLcdPresentation(),'passthrough');f.api.setShowLcd(false);assert.ok(f.api.getInputTicket());assert.deepEqual(f.sent,[]);
});
for(const boundary of ['blur','pagehide','resize','orientationchange','hidden','viewport','library']){
    test('mobile '+boundary+' cancels queued callbacks without replay or native writes',()=>{
        const f=fixture();f.api.clickTile(3,1);const callbacks=[...f.timers.values()].map(x=>x.fn);f.focus(2,1);
        if(boundary==='hidden')f.hidden(true);else if(boundary==='viewport')f.viewport();
        else if(boundary==='library')f.env.libraryChanged();else f.emit(boundary);
        callbacks.forEach(fn=>fn());f.tick(1000);assert.deepEqual(f.sent,[K.RIGHT]);assert.deepEqual(f.writes,[]);
        assert.equal(f.api.debugSnapshot().transaction,null);
        if(boundary==='hidden')f.hidden(false);f.poll();assert.deepEqual(f.sent,[K.RIGHT]);
    });
}
test('mobile presentation mode change and explicit retire emit no native input',()=>{
    const f=fixture();f.api.retireInteraction('owner-changed');f.api.setShowLcd(true);f.api.setMode('classic');
    f.api.setMode('hd');assert.deepEqual(f.sent,[]);assert.deepEqual(f.writes,[]);
    assert.equal(f.env.baye.hooks.fightOpenMainMenu,undefined);
});
